// Package consumer — Pact consumer contract tests for
// admin-bff → identity-svc UserService.LookupKeycloakProfilesByIds.
//
// Pins the static contract admin-bff-identity-svc.json so that any
// structural drift (dropped interaction, changed path, renamed field) fails
// the gate before `make pact-publish SVC=admin-bff` uploads it to the broker.
//
// The LookupKeycloakProfilesByIds RPC proxies to the Keycloak Admin API.
// Platform-admin accounts live only in the Keycloak realm and have no
// identity.users row, so this RPC (not LookupUsersByKeycloakIds) is the only
// way to resolve their display names for the feature-flag updated_by field.
package consumer

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/stretchr/testify/require"
)

const identityPactPath = "../../../pacts/admin-bff-identity-svc.json"

// identityPactContract is the minimal struct for reading the static Pact v2
// JSON. Interaction bodies are map[string]any so the tests do not depend on
// proto-generated types.
type identityPactContract struct {
	Consumer struct {
		Name string `json:"name"`
	} `json:"consumer"`
	Provider struct {
		Name string `json:"name"`
	} `json:"provider"`
	Interactions []identityPactInteraction `json:"interactions"`
}

type identityPactInteraction struct {
	Description    string `json:"description"`
	ProviderStates []struct {
		Name string `json:"name"`
	} `json:"providerStates"`
	Request struct {
		Method string         `json:"method"`
		Path   string         `json:"path"`
		Body   map[string]any `json:"body"`
	} `json:"request"`
	Response struct {
		Status int            `json:"status"`
		Body   map[string]any `json:"body"`
	} `json:"response"`
}

const lookupKeycloakProfilesPath = "/omnicore.identity.user.v1.UserService/LookupKeycloakProfilesByIds"

// Platform user management RPCs — each appears exactly once in this
// contract (unlike lookupKeycloakProfilesPath, which two interactions
// share and disambiguate by description), so findIdentityInteractionByPath
// needs no description fragment.
const (
	listPlatformUsersPath = "/omnicore.identity.user.v1.UserService/ListPlatformUsers"
	resetPasswordPath     = "/omnicore.identity.user.v1.UserService/ResetPassword"
	deleteAccountPath     = "/omnicore.identity.user.v1.UserService/DeleteAccount"
	isPlatformAdminPath   = "/omnicore.identity.user.v1.UserService/IsPlatformAdmin"
)

// loadIdentityContract reads + parses the identity-svc pact file and asserts
// participant names.
func loadIdentityContract(t *testing.T) identityPactContract {
	t.Helper()
	raw, err := os.ReadFile(identityPactPath)
	require.NoError(t, err, "read identity-svc pact contract")
	var c identityPactContract
	require.NoError(t, json.Unmarshal(raw, &c), "parse identity-svc pact contract as JSON")
	require.Equal(t, "admin-bff", c.Consumer.Name,
		"consumer must be admin-bff")
	require.Equal(t, "identity-svc", c.Provider.Name,
		"provider must be identity-svc")
	return c
}

// findIdentityInteraction locates an interaction by gRPC path + description fragment.
func findIdentityInteraction(c identityPactContract, descFragment string) (identityPactInteraction, bool) {
	for _, it := range c.Interactions {
		if it.Request.Path == lookupKeycloakProfilesPath && containsStr(it.Description, descFragment) {
			return it, true
		}
	}
	return identityPactInteraction{}, false
}

// findIdentityInteractionByPath locates the single interaction on the given
// gRPC path. Unlike findIdentityInteraction (needed because two
// interactions SHARE lookupKeycloakProfilesPath and must be disambiguated
// by description), each of ListPlatformUsers, ResetPassword, and
// DeleteAccount appears exactly once in this contract, so the path alone
// is unambiguous.
func findIdentityInteractionByPath(c identityPactContract, path string) (identityPactInteraction, bool) {
	for _, it := range c.Interactions {
		if it.Request.Path == path {
			return it, true
		}
	}
	return identityPactInteraction{}, false
}

func containsStr(s, sub string) bool {
	return len(s) >= len(sub) && (s == sub || len(s) > 0 && findSubstr(s, sub))
}

func findSubstr(s, sub string) bool {
	if len(sub) == 0 {
		return true
	}
	for i := 0; i <= len(s)-len(sub); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

// TestPactIdentityContractFileExists asserts the pact JSON lives at the
// expected path — a missing file would silently stop the gate from publishing
// anything.
func TestPactIdentityContractFileExists(t *testing.T) {
	_, err := os.Stat(identityPactPath)
	require.NoError(t, err,
		"pact contract should be at services/admin-bff/pacts/admin-bff-identity-svc.json")
}

// TestPactIdentityContract_DeclaresExpectedInteractions guards the count so
// a silently-dropped OR silently-added interaction fails the gate.
//
// Deliberately NOT named "...DeclaresExactlyNInteractions": that was this
// test's original name, and it went stale the moment a later change (adding
// ListPlatformUsers/ResetPassword/DeleteAccount) grew the contract without
// updating the name or the assertion — the test kept passing its own
// (now-wrong) expectation for as long as nobody looked at the number in the
// message. Baking the count into the name only invites the same drift next
// time an interaction is added.
func TestPactIdentityContract_DeclaresExpectedInteractions(t *testing.T) {
	c := loadIdentityContract(t)
	require.Len(t, c.Interactions, 6,
		"contract must declare exactly 6 interactions: LookupKeycloakProfilesByIds "+
			"(resolved + not-found) + ListPlatformUsers + ResetPassword + DeleteAccount + "+
			"IsPlatformAdmin")
}

// TestPactIdentityContract_ResolvedProfile pins the interaction where the
// Keycloak user exists and identity-svc returns their display name.
func TestPactIdentityContract_ResolvedProfile(t *testing.T) {
	c := loadIdentityContract(t)

	it, ok := findIdentityInteraction(c, "resolves a platform-admin Keycloak UUID to a display name")
	require.True(t, ok, "contract must declare a resolved-profile interaction")

	// Provider state names the Keycloak user seeded in identity-svc's fake IdP.
	require.Len(t, it.ProviderStates, 1)
	require.Contains(t, it.ProviderStates[0].Name, "kc-admin-uuid-01",
		"provider state must identify the Keycloak user UUID being seeded")

	// Request carries the batch of IDs.
	require.Equal(t, "POST", it.Request.Method)
	ids, ok := it.Request.Body["ids"].([]any)
	require.True(t, ok, "request body must carry an ids array")
	require.Len(t, ids, 1, "request must ask for exactly one ID in this interaction")
	require.Equal(t, "kc-admin-uuid-01", ids[0], "request must carry the correct Keycloak UUID")

	// Response: profiles array with one entry.
	require.Equal(t, 200, it.Response.Status)
	profiles, ok := it.Response.Body["profiles"].([]any)
	require.True(t, ok, "response body must carry a profiles array")
	require.Len(t, profiles, 1, "response must include exactly one profile for the resolved UUID")

	profile, ok := profiles[0].(map[string]any)
	require.True(t, ok, "each profile must be an object")
	require.Equal(t, "kc-admin-uuid-01", profile["id"],
		"profile.id must match the requested Keycloak UUID")
	require.Equal(t, "Alice Smith", profile["display_name"],
		"profile.display_name must be the composed FirstName+LastName")
}

// TestPactIdentityContract_UnknownProfile pins the interaction where the
// Keycloak user does NOT exist — identity-svc returns an empty profiles array
// rather than an error, consistent with the not-found → nil behaviour in
// idp.GetUserProfile.
func TestPactIdentityContract_UnknownProfile(t *testing.T) {
	c := loadIdentityContract(t)

	it, ok := findIdentityInteraction(c, "unknown Keycloak UUID returns empty profiles")
	require.True(t, ok, "contract must declare an unknown-profile interaction")

	// Provider state signals no user exists for this UUID.
	require.Len(t, it.ProviderStates, 1)
	require.Contains(t, it.ProviderStates[0].Name, "kc-missing-uuid-99",
		"provider state must identify the missing Keycloak UUID")

	// Request carries the missing ID.
	require.Equal(t, "POST", it.Request.Method)
	ids, ok := it.Request.Body["ids"].([]any)
	require.True(t, ok, "request body must carry an ids array")
	require.Len(t, ids, 1)
	require.Equal(t, "kc-missing-uuid-99", ids[0])

	// Response: empty profiles array, NOT a 404 error.
	require.Equal(t, 200, it.Response.Status)
	profiles, ok := it.Response.Body["profiles"].([]any)
	require.True(t, ok, "response body must carry a profiles array (even when empty)")
	require.Empty(t, profiles,
		"response profiles must be empty when the Keycloak user does not exist")
}

// TestPactIdentityContract_ListPlatformUsers pins the platform-wide browse
// interaction backing the system-admin Users surface: filtering by an exact
// keycloak_user_id resolves the one grouped person, who belongs to two orgs.
func TestPactIdentityContract_ListPlatformUsers(t *testing.T) {
	c := loadIdentityContract(t)

	it, ok := findIdentityInteractionByPath(c, listPlatformUsersPath)
	require.True(t, ok, "contract must declare a ListPlatformUsers interaction")

	require.Len(t, it.ProviderStates, 1)
	require.Contains(t, it.ProviderStates[0].Name, "00000000-0000-4000-8000-000000000101",
		"provider state must identify the seeded platform user")

	require.Equal(t, "POST", it.Request.Method)
	require.Equal(t, "00000000-0000-4000-8000-000000000101", it.Request.Body["keycloak_user_id"],
		"request must filter by the exact keycloak_user_id")

	require.Equal(t, 200, it.Response.Status)
	users, ok := it.Response.Body["users"].([]any)
	require.True(t, ok, "response body must carry a users array")
	require.Len(t, users, 1, "response must include exactly the one matched person")

	user, ok := users[0].(map[string]any)
	require.True(t, ok, "each user entry must be an object")
	require.Equal(t, "00000000-0000-4000-8000-000000000101", user["keycloak_user_id"])
	require.Equal(t, "platform.user@example.com", user["email"])
	require.EqualValues(t, 2, user["workspace_count"],
		"workspace_count must reflect the two orgs the person was seeded into")
}

// TestPactIdentityContract_ResetPassword pins the temporary-credential
// interaction: the response carries the show-once temporary_password field.
func TestPactIdentityContract_ResetPassword(t *testing.T) {
	c := loadIdentityContract(t)

	it, ok := findIdentityInteractionByPath(c, resetPasswordPath)
	require.True(t, ok, "contract must declare a ResetPassword interaction")

	require.Len(t, it.ProviderStates, 1)
	require.Contains(t, it.ProviderStates[0].Name, "00000000-0000-4000-8000-000000000102",
		"provider state must identify the seeded target user")

	require.Equal(t, "POST", it.Request.Method)
	require.Equal(t, "00000000-0000-4000-8000-000000000102", it.Request.Body["user_id"])

	require.Equal(t, 200, it.Response.Status)
	require.Equal(t, "tmp-pass-pact-fixture", it.Response.Body["temporary_password"],
		"response must carry the show-once temporary password")
}

// TestPactIdentityContract_DeleteAccount pins the terminal Keycloak-purge
// interaction: the response reports keycloak_deleted=true.
func TestPactIdentityContract_DeleteAccount(t *testing.T) {
	c := loadIdentityContract(t)

	it, ok := findIdentityInteractionByPath(c, deleteAccountPath)
	require.True(t, ok, "contract must declare a DeleteAccount interaction")

	require.Len(t, it.ProviderStates, 1)
	require.Contains(t, it.ProviderStates[0].Name, "00000000-0000-4000-8000-000000000103",
		"provider state must identify the seeded target user")

	require.Equal(t, "POST", it.Request.Method)
	require.Equal(t, "00000000-0000-4000-8000-000000000103", it.Request.Body["user_id"])

	require.Equal(t, 200, it.Response.Status)
	require.Equal(t, true, it.Response.Body["keycloak_deleted"],
		"response must confirm the Keycloak account was purged")
}

// TestPactIdentityContract_IsPlatformAdmin pins the admin-target PRE-FLIGHT
// interaction admin-bff's Delete fan-out calls before mutating any org
// membership (finding #2322-1's fix): the response carries is_admin, a plain
// bool with no per-org data, matching the RPC's read-only, single-check
// shape.
func TestPactIdentityContract_IsPlatformAdmin(t *testing.T) {
	c := loadIdentityContract(t)

	it, ok := findIdentityInteractionByPath(c, isPlatformAdminPath)
	require.True(t, ok, "contract must declare an IsPlatformAdmin interaction")

	require.Len(t, it.ProviderStates, 1)
	require.Contains(t, it.ProviderStates[0].Name, "00000000-0000-4000-8000-000000000104",
		"provider state must identify the seeded target user")

	require.Equal(t, "POST", it.Request.Method)
	require.Equal(t, "00000000-0000-4000-8000-000000000104", it.Request.Body["user_id"])

	require.Equal(t, 200, it.Response.Status)
	require.Equal(t, false, it.Response.Body["is_admin"],
		"response must report whether the target holds the admin role")
}


