// Package consumer — Pact consumer contract tests for
// admin-bff → org-svc FeatureFlagService.
//
// Pins the static contract admin-bff-org-svc-feature-flag.json so that any
// structural drift (dropped interaction, changed path, renamed field) fails
// the gate before `make pact-publish SVC=admin-bff` uploads it to the broker.
//
// The org.platform_feature_flag table is platform-global (no org_id column).
// However, admin-bff forwards the platform admin's own org_id as x-tenant-id
// so that SetFeatureFlag's outbox write inside WithTxAsActor satisfies the
// outbox RLS WITH CHECK. The forwarded tenant appears as a gRPC metadata
// header — it is NOT a field in the proto request body, which is why the
// request bodies in this contract carry no tenant_id field.
package consumer

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/stretchr/testify/require"
)

const featureFlagPactPath = "../../../pacts/admin-bff-org-svc-feature-flag.json"

// featureFlagPactContract is the minimal struct for reading the static Pact
// v3 JSON. Interaction bodies are map[string]any so the tests do not depend
// on proto-generated types.
type featureFlagPactContract struct {
	Consumer struct {
		Name string `json:"name"`
	} `json:"consumer"`
	Provider struct {
		Name string `json:"name"`
	} `json:"provider"`
	Interactions []featureFlagInteraction `json:"interactions"`
}

type featureFlagInteraction struct {
	Description    string `json:"description"`
	ProviderStates []struct {
		Name string `json:"name"`
	} `json:"providerStates"`
	Request struct {
		Method string         `json:"method"`
		Path   string         `json:"path"`
		Body   map[string]any `json:"body"`
	} `json:"request"`
	Response struct {
		Status int            `json:"status"`
		Body   map[string]any `json:"body"`
	} `json:"response"`
}

const (
	listFlagsPath = "/omnicore.org.feature_flag.v1.FeatureFlagService/ListFeatureFlags"
	setFlagPath   = "/omnicore.org.feature_flag.v1.FeatureFlagService/SetFeatureFlag"
)

// loadFeatureFlagContract reads + parses the feature-flag pact file and
// asserts participant names.
func loadFeatureFlagContract(t *testing.T) featureFlagPactContract {
	t.Helper()
	raw, err := os.ReadFile(featureFlagPactPath)
	require.NoError(t, err, "read feature-flag pact contract")
	var c featureFlagPactContract
	require.NoError(t, json.Unmarshal(raw, &c), "parse feature-flag pact contract as JSON")
	require.Equal(t, "admin-bff", c.Consumer.Name)
	require.Equal(t, "org-svc", c.Provider.Name)
	return c
}

// findFFInteraction locates an interaction by gRPC path.
func findFFInteraction(c featureFlagPactContract, path string) (featureFlagInteraction, bool) {
	for _, it := range c.Interactions {
		if it.Request.Path == path {
			return it, true
		}
	}
	return featureFlagInteraction{}, false
}

// TestPactFeatureFlagContractFileExists asserts the pact JSON lives at the
// expected path — a missing file would silently stop the gate from publishing
// anything.
func TestPactFeatureFlagContractFileExists(t *testing.T) {
	_, err := os.Stat(featureFlagPactPath)
	require.NoError(t, err,
		"pact contract should be at services/admin-bff/pacts/admin-bff-org-svc-feature-flag.json")
}

// TestPactFeatureFlagContract_DeclaresExactlyTwoInteractions guards the count
// so a silently-dropped interaction fails the gate.
func TestPactFeatureFlagContract_DeclaresExactlyTwoInteractions(t *testing.T) {
	c := loadFeatureFlagContract(t)
	require.Len(t, c.Interactions, 2,
		"contract must declare exactly 2 interactions: ListFeatureFlags + SetFeatureFlag")
}

// TestPactFeatureFlagContract_ListFeatureFlags pins the list interaction:
// no request body fields (ListFeatureFlagsRequest has no proto fields),
// response carries eleven flag objects (dialogue/range/spaces/studio/ask/
// workflows/clio/files/monitor/queue/rooms), all default-enabled. The admin's org
// travels as x-tenant-id gRPC metadata, not as a request body field.
func TestPactFeatureFlagContract_ListFeatureFlags(t *testing.T) {
	c := loadFeatureFlagContract(t)

	it, ok := findFFInteraction(c, listFlagsPath)
	require.True(t, ok, "contract must declare a ListFeatureFlags interaction")

	// Provider state carries no tenant UUID in its name.
	require.Len(t, it.ProviderStates, 1)
	require.Equal(t,
		"platform feature flags exist with default values",
		it.ProviderStates[0].Name,
		"provider state must be the platform-global default-values state")

	// Request body: empty (proto ListFeatureFlagsRequest has no fields).
	// The admin's org is NOT a body field — it travels as x-tenant-id metadata.
	require.Equal(t, "POST", it.Request.Method)
	require.NotContains(t, it.Request.Body, "tenant_id",
		"ListFeatureFlags request body must carry no tenant_id proto field — tenant is a gRPC metadata header")

	// Response: eleven flags, all enabled.
	require.Equal(t, 200, it.Response.Status)
	flags, ok := it.Response.Body["flags"].([]any)
	require.True(t, ok, "response body must carry a flags array")
	require.Len(t, flags, 11, "response must include entries for dialogue, range, spaces, studio, ask, workflows, clio, files, monitor, queue, and rooms")

	// Collect flag objects for assertion.
	flagMap := make(map[string]any)
	for _, raw := range flags {
		f, ok := raw.(map[string]any)
		require.True(t, ok, "each flag entry must be an object")
		key, _ := f["key"].(string)
		require.NotEmpty(t, key, "flag entry must have a key field")
		flagMap[key] = f
	}
	for _, key := range []string{"dialogue", "range", "spaces", "studio", "ask", "workflows", "clio", "files", "monitor", "queue", "rooms"} {
		require.Contains(t, flagMap, key, "flags must include %q", key)
		f, _ := flagMap[key].(map[string]any)
		enabled, _ := f["enabled"].(bool)
		require.True(t, enabled, "default flag %q must be enabled=true", key)
	}
}

// TestPactFeatureFlagContract_SetFeatureFlag pins the set interaction:
// request carries key="range" + enabled=false; response echoes the updated
// flag post-image. The admin's org is forwarded as x-tenant-id gRPC metadata
// (not as a request body field) so the outbox RLS is satisfied server-side.
func TestPactFeatureFlagContract_SetFeatureFlag(t *testing.T) {
	c := loadFeatureFlagContract(t)

	it, ok := findFFInteraction(c, setFlagPath)
	require.True(t, ok, "contract must declare a SetFeatureFlag interaction")

	// Provider state carries no tenant UUID in its name — the seeded admin org
	// is opaque to the contract body; only the gRPC metadata carries it.
	require.Len(t, it.ProviderStates, 1)
	require.Equal(t,
		"platform feature flags exist with default values",
		it.ProviderStates[0].Name)

	// Request body: key=range, enabled=false. The admin's org is NOT a body
	// field — it travels as the x-tenant-id gRPC metadata header.
	require.Equal(t, "POST", it.Request.Method)
	require.Equal(t, "range", it.Request.Body["key"],
		"request body must carry key=range")
	require.Equal(t, false, it.Request.Body["enabled"],
		"request body must carry enabled=false")
	require.NotContains(t, it.Request.Body, "tenant_id",
		"SetFeatureFlag request body must carry no tenant_id proto field — tenant is a gRPC metadata header")

	// Response: echoes updated flag.
	require.Equal(t, 200, it.Response.Status)
	flag, ok := it.Response.Body["flag"].(map[string]any)
	require.True(t, ok, "response body must carry a flag object")
	require.Equal(t, "range", flag["key"], "response flag.key must be range")
	require.Equal(t, false, flag["enabled"], "response flag.enabled must be false")
}


