// Package consumer — Pact consumer contract tests for
// admin-bff → org-svc ProviderKeyService.
//
// Pins the static contract admin-bff-org-svc-provider-key.json so that any
// structural drift (dropped interaction, changed path, renamed field, or a
// leaked secret) fails the gate before `make pact-publish SVC=admin-bff`
// uploads it to the broker.
//
// The org.provider_key table is platform-global (no org_id column, no RLS).
// However, admin-bff forwards the platform admin's own org_id as x-tenant-id
// so that SetProviderKey's outbox write inside WithTxAsActor satisfies the
// outbox RLS WITH CHECK. The forwarded tenant appears as a gRPC metadata
// header — it is NOT a field in the proto request body, which is why the
// request bodies in this contract carry no tenant_id field.
//
// The raw secret is NEVER returned by any RPC: neither ListProviderKeys nor
// SetProviderKey's response body carries an api_key field — only presence
// metadata (provider / configured / vault_path). SetProviderKey's REQUEST
// necessarily carries api_key (the proto field the admin types), so this test
// also guards that the contract never pins a value shaped like a real secret.
package consumer

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/stretchr/testify/require"
)

const providerKeyPactPath = "../../../pacts/admin-bff-org-svc-provider-key.json"

// providerKeyPactContract is the minimal struct for reading the static Pact
// v3 JSON. Interaction bodies are map[string]any so the tests do not depend
// on proto-generated types.
type providerKeyPactContract struct {
	Consumer struct {
		Name string `json:"name"`
	} `json:"consumer"`
	Provider struct {
		Name string `json:"name"`
	} `json:"provider"`
	Interactions []providerKeyInteraction `json:"interactions"`
}

type providerKeyInteraction struct {
	Description    string `json:"description"`
	ProviderStates []struct {
		Name string `json:"name"`
	} `json:"providerStates"`
	Request struct {
		Method string         `json:"method"`
		Path   string         `json:"path"`
		Body   map[string]any `json:"body"`
	} `json:"request"`
	Response struct {
		Status int            `json:"status"`
		Body   map[string]any `json:"body"`
	} `json:"response"`
}

const (
	listProviderKeysPath = "/omnicore.org.provider_key.v1.ProviderKeyService/ListProviderKeys"
	setProviderKeyPath   = "/omnicore.org.provider_key.v1.ProviderKeyService/SetProviderKey"
)

// loadProviderKeyContract reads + parses the provider-key pact file and
// asserts participant names.
func loadProviderKeyContract(t *testing.T) providerKeyPactContract {
	t.Helper()
	raw, err := os.ReadFile(providerKeyPactPath)
	require.NoError(t, err, "read provider-key pact contract")
	var c providerKeyPactContract
	require.NoError(t, json.Unmarshal(raw, &c), "parse provider-key pact contract as JSON")
	require.Equal(t, "admin-bff", c.Consumer.Name)
	require.Equal(t, "org-svc", c.Provider.Name)
	return c
}

// findPKInteraction locates an interaction by gRPC path.
func findPKInteraction(c providerKeyPactContract, path string) (providerKeyInteraction, bool) {
	for _, it := range c.Interactions {
		if it.Request.Path == path {
			return it, true
		}
	}
	return providerKeyInteraction{}, false
}

// TestPactProviderKeyContractFileExists asserts the pact JSON lives at the
// expected path — a missing file would silently stop the gate from publishing
// anything.
func TestPactProviderKeyContractFileExists(t *testing.T) {
	_, err := os.Stat(providerKeyPactPath)
	require.NoError(t, err,
		"pact contract should be at services/admin-bff/pacts/admin-bff-org-svc-provider-key.json")
}

// TestPactProviderKeyContract_DeclaresExactlyTwoInteractions guards the count
// so a silently-dropped interaction fails the gate.
func TestPactProviderKeyContract_DeclaresExactlyTwoInteractions(t *testing.T) {
	c := loadProviderKeyContract(t)
	require.Len(t, c.Interactions, 2,
		"contract must declare exactly 2 interactions: ListProviderKeys + SetProviderKey")
}

// TestPactProviderKeyContract_ListProviderKeys pins the list interaction:
// no request body fields (ListProviderKeysRequest has no proto fields),
// response carries one entry per known provider (apify/jina/serper) with
// presence metadata only. The admin's org travels as x-tenant-id gRPC
// metadata, not as a request body field, and the raw secret is never returned.
func TestPactProviderKeyContract_ListProviderKeys(t *testing.T) {
	c := loadProviderKeyContract(t)

	it, ok := findPKInteraction(c, listProviderKeysPath)
	require.True(t, ok, "contract must declare a ListProviderKeys interaction")

	// Provider state carries no tenant UUID in its name.
	require.Len(t, it.ProviderStates, 1)
	require.Equal(t,
		"platform provider keys exist with serper configured",
		it.ProviderStates[0].Name,
		"provider state must be the platform-global serper-configured state")

	// Request body: empty (proto ListProviderKeysRequest has no fields).
	// The admin's org is NOT a body field — it travels as x-tenant-id metadata.
	require.Equal(t, "POST", it.Request.Method)
	require.NotContains(t, it.Request.Body, "tenant_id",
		"ListProviderKeys request body must carry no tenant_id proto field — tenant is a gRPC metadata header")

	// Response: three provider entries.
	require.Equal(t, 200, it.Response.Status)
	keys, ok := it.Response.Body["keys"].([]any)
	require.True(t, ok, "response body must carry a keys array")
	require.Len(t, keys, 3, "response must include one entry per known provider: apify, jina, serper")

	// Collect key objects for assertion, and guard the secret discipline.
	keyMap := make(map[string]any)
	for _, raw := range keys {
		k, ok := raw.(map[string]any)
		require.True(t, ok, "each key entry must be an object")
		provider, _ := k["provider"].(string)
		require.NotEmpty(t, provider, "key entry must have a provider field")
		require.NotContains(t, k, "api_key",
			"ListProviderKeys response must NEVER carry the raw secret (api_key)")
		keyMap[provider] = k
	}
	for _, provider := range []string{"PROVIDER_APIFY", "PROVIDER_JINA", "PROVIDER_SERPER"} {
		require.Contains(t, keyMap, provider, "keys must include %q", provider)
	}

	// The seeded serper entry is configured with its Vault path ref (never the
	// secret); apify/jina are unconfigured.
	serper, _ := keyMap["PROVIDER_SERPER"].(map[string]any)
	require.Equal(t, true, serper["configured"], "serper must be configured=true")
	require.Equal(t, "platform/providers/serper", serper["vault_path"],
		"serper must carry its per-provider Vault path ref (a locator, never the secret)")
	for _, provider := range []string{"PROVIDER_APIFY", "PROVIDER_JINA"} {
		entry, _ := keyMap[provider].(map[string]any)
		require.Equal(t, false, entry["configured"], "%s must be configured=false", provider)
	}
}

// TestPactProviderKeyContract_SetProviderKey pins the set interaction:
// request carries provider="PROVIDER_SERPER" + an api_key placeholder;
// response echoes the stored key's presence metadata (provider + configured +
// vault_path) and NEVER the secret. The admin's org is forwarded as
// x-tenant-id gRPC metadata (not a request body field) so the outbox RLS is
// satisfied server-side.
func TestPactProviderKeyContract_SetProviderKey(t *testing.T) {
	c := loadProviderKeyContract(t)

	it, ok := findPKInteraction(c, setProviderKeyPath)
	require.True(t, ok, "contract must declare a SetProviderKey interaction")

	require.Len(t, it.ProviderStates, 1)
	require.Equal(t,
		"platform provider keys exist with serper configured",
		it.ProviderStates[0].Name)

	// Request body: provider + api_key. The admin's org is NOT a body field —
	// it travels as the x-tenant-id gRPC metadata header.
	require.Equal(t, "POST", it.Request.Method)
	require.Equal(t, "PROVIDER_SERPER", it.Request.Body["provider"],
		"request body must carry provider=PROVIDER_SERPER")
	require.NotContains(t, it.Request.Body, "tenant_id",
		"SetProviderKey request body must carry no tenant_id proto field — tenant is a gRPC metadata header")

	// The api_key request field is legitimate (it is what the admin types), but
	// the contract must never pin a value shaped like a real credential.
	apiKey, ok := it.Request.Body["api_key"].(string)
	require.True(t, ok, "request body must carry an api_key field")
	require.Contains(t, apiKey, "placeholder",
		"SetProviderKey contract must pin a clearly-fake placeholder api_key, never a real secret")

	// Response: echoes the stored key's presence metadata, never the secret.
	require.Equal(t, 200, it.Response.Status)
	key, ok := it.Response.Body["key"].(map[string]any)
	require.True(t, ok, "response body must carry a key object")
	require.Equal(t, "PROVIDER_SERPER", key["provider"], "response key.provider must be PROVIDER_SERPER")
	require.Equal(t, true, key["configured"], "response key.configured must be true after a set")
	require.Equal(t, "platform/providers/serper", key["vault_path"],
		"response key.vault_path must be the per-provider Vault path ref (a locator, never the secret)")
	require.NotContains(t, key, "api_key",
		"SetProviderKey response must NEVER echo the raw secret (api_key)")
}


