// Package consumer — Pact consumer contract tests for admin-bff → org-svc.
//
// Pins the static Pact contract file for the four org-svc TenantService
// membership RPCs admin-bff relies on: the three writes the "roles on
// organization members" feature needs (UpdateMembershipRole, AddMember,
// RemoveMember) plus the workspace roster read AssignUserModal performs
// (ListMembershipsByTenant against a CHILD workspace). org-svc gates all four
// on the caller's org role, so each provider state describes BOTH the data
// AND the caller's authorization.
//
// The contract JSON is authored statically (consistent with shell-bff's
// shell-bff-org-svc.json, which uses the same approach). This test is a CI
// gate: if the file is deleted, the path changes, or a documented interaction
// is dropped or drifts, the test fails before `make pact-publish SVC=admin-bff`
// ever uploads it.
package consumer

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/stretchr/testify/require"
)

const orgPactPath = "../../../pacts/admin-bff-org-svc.json"

// pactContract is the minimal projection of the Pact v3 contract this test
// asserts against. It mirrors the static JSON shape under pacts/.
type pactContract struct {
	Consumer struct {
		Name string `json:"name"`
	} `json:"consumer"`
	Provider struct {
		Name string `json:"name"`
	} `json:"provider"`
	Interactions []pactInteraction `json:"interactions"`
}

type pactInteraction struct {
	Description    string `json:"description"`
	ProviderStates []struct {
		Name string `json:"name"`
	} `json:"providerStates"`
	Request struct {
		Method string                 `json:"method"`
		Path   string                 `json:"path"`
		Body   map[string]interface{} `json:"body"`
	} `json:"request"`
	Response struct {
		Status int                    `json:"status"`
		Body   map[string]interface{} `json:"body"`
	} `json:"response"`
}

const (
	// Concrete UUIDs the provider-state seeders (org-svc side) will use. The
	// caller is an ADMIN of the org and is the actor for all three RPCs.
	callerID = "00000000-0000-0000-0000-000000000a01"
	orgID    = "00000000-0000-0000-0000-000000000b01"

	// workspaceID is a CHILD tenant of orgID — the roster-read interaction
	// deliberately targets a workspace, not the org root, because that is the
	// branch of org-svc's authorizeRosterRead that is actually gated.
	workspaceID = "00000000-0000-0000-0000-000000000b02"

	// Subject users — one per interaction so findInteraction can disambiguate.
	updateUserID = "00000000-0000-0000-0000-000000000c01" // role updated MEMBER → ADMIN
	addUserID    = "00000000-0000-0000-0000-000000000c02" // added as MEMBER
	removeUserID = "00000000-0000-0000-0000-000000000c03" // removed

	updatePath = "/omnicore.org.tenant.v1.TenantService/UpdateMembershipRole"
	addPath    = "/omnicore.org.tenant.v1.TenantService/AddMember"
	removePath = "/omnicore.org.tenant.v1.TenantService/RemoveMember"

	// checkRemovablePath's interaction backs admin-bff's platform-delete
	// pre-flight (CheckUserRemovable) — added to this same contract file
	// after the three membership RPCs above; it appears exactly once, so
	// findInteractionByPath needs no user_id disambiguator.
	checkRemovablePath = "/omnicore.org.tenant.v1.TenantService/CheckUserRemovable"

	// Subject + org for the CheckUserRemovable interaction — distinct from
	// callerID/orgID above because the pre-flight seeds its own tenant.
	checkRemovableOrgID  = "00000000-0000-4000-8000-000000000201"
	checkRemovableUserID = "00000000-0000-4000-8000-000000000104"

	rosterPath = "/omnicore.org.tenant.v1.TenantService/ListMembershipsByTenant"
)

func TestPactOrgContractFileExists(t *testing.T) {
	_, err := os.Stat(orgPactPath)
	require.NoError(t, err,
		"pact contract should be at services/admin-bff/pacts/admin-bff-org-svc.json")
}

// loadOrgContract reads + parses the static admin-bff↔org-svc contract and
// pins the participant names.
func loadOrgContract(t *testing.T) pactContract {
	t.Helper()
	raw, err := os.ReadFile(orgPactPath)
	require.NoError(t, err, "read org-svc pact contract")
	var c pactContract
	require.NoError(t, json.Unmarshal(raw, &c), "parse org-svc pact contract as JSON")
	require.Equal(t, "admin-bff", c.Consumer.Name)
	require.Equal(t, "org-svc", c.Provider.Name)
	return c
}

// findInteraction returns the interaction whose request targets the given
// gRPC path AND whose request body's user_id matches, so the three membership
// interactions stay distinguishable even though they share a tenant + caller.
func findInteraction(c pactContract, path, userID string) (pactInteraction, bool) {
	for _, it := range c.Interactions {
		if it.Request.Path != path {
			continue
		}
		if uid, _ := it.Request.Body["user_id"].(string); uid == userID {
			return it, true
		}
	}
	return pactInteraction{}, false
}

// findInteractionByPath returns the sole interaction targeting the given gRPC
// path. Unlike findInteraction it does not key on user_id — the roster read
// carries only a tenant_id — so it also asserts the path is unambiguous.
func findInteractionByPath(t *testing.T, c pactContract, path string) pactInteraction {
	t.Helper()
	var found []pactInteraction
	for _, it := range c.Interactions {
		if it.Request.Path == path {
			found = append(found, it)
		}
	}
	require.Lenf(t, found, 1, "contract must declare exactly one interaction for %s", path)
	return found[0]
}

// TestPactOrgContract_DeclaresExpectedInteractions guards the count so a
// silently-dropped OR silently-added interaction fails the gate.
//
// Deliberately NOT named for its count: earlier revisions of this test were
// called "...DeclaresThreeMembershipInteractions" and then
// "...DeclaresFourMembershipInteractions", and each went stale the moment a
// later change grew the contract without updating the name. Baking the count
// into the name only invites the same drift the next time an interaction is
// added.
func TestPactOrgContract_DeclaresExpectedInteractions(t *testing.T) {
	c := loadOrgContract(t)
	require.Len(t, c.Interactions, 5,
		"contract must declare exactly 5 interactions: the 3 membership writes "+
			"(UpdateMembershipRole, AddMember, RemoveMember) + the workspace "+
			"roster read (ListMembershipsByTenant) + CheckUserRemovable")
}

// TestPactOrgContract_UpdateMembershipRole pins the role-change interaction:
// an org ADMIN promotes a MEMBER to ADMIN; org-svc echoes the post-image
// Membership with the new role, which orgclient.UpdateMembershipRole returns.
func TestPactOrgContract_UpdateMembershipRole(t *testing.T) {
	c := loadOrgContract(t)

	it, ok := findInteraction(c, updatePath, updateUserID)
	require.True(t, ok, "contract must declare an UpdateMembershipRole interaction")

	require.Len(t, it.ProviderStates, 1)
	require.Equal(t,
		"caller "+callerID+" is an ADMIN of org "+orgID+" and user "+updateUserID+" is a MEMBER of workspace "+orgID,
		it.ProviderStates[0].Name,
		"provider state must seed BOTH the caller's ADMIN authz AND the target membership")

	require.Equal(t, "POST", it.Request.Method)
	require.Equal(t, orgID, it.Request.Body["tenant_id"])
	require.Equal(t, updateUserID, it.Request.Body["user_id"])
	require.Equal(t, "MEMBERSHIP_ROLE_ADMIN", it.Request.Body["role"],
		"role is the MembershipRole enum, serialized as its canonical wire name")

	require.Equal(t, 200, it.Response.Status)
	membership, ok := it.Response.Body["membership"].(map[string]interface{})
	require.True(t, ok, "response must wrap the post-image in a membership object")
	require.Equal(t, "00000000-0000-0000-0000-000000000d01", membership["id"])
	require.Equal(t, orgID, membership["tenant_id"])
	require.Equal(t, updateUserID, membership["user_id"])
	require.Equal(t, "MEMBERSHIP_ROLE_ADMIN", membership["role"],
		"echoed role must reflect the requested change")
}

// TestPactOrgContract_AddMember pins the add-member interaction: an org ADMIN
// adds a not-yet-member user as MEMBER; org-svc returns the created Membership,
// which orgclient.AddMemberByID surfaces.
func TestPactOrgContract_AddMember(t *testing.T) {
	c := loadOrgContract(t)

	it, ok := findInteraction(c, addPath, addUserID)
	require.True(t, ok, "contract must declare an AddMember interaction")

	require.Len(t, it.ProviderStates, 1)
	require.Equal(t,
		"caller "+callerID+" is an ADMIN of org "+orgID+" and user "+addUserID+" is not yet a member of workspace "+orgID,
		it.ProviderStates[0].Name,
		"provider state must seed the caller's ADMIN authz AND assert the target is not already a member")

	require.Equal(t, "POST", it.Request.Method)
	require.Equal(t, orgID, it.Request.Body["tenant_id"])
	require.Equal(t, addUserID, it.Request.Body["user_id"])
	require.Equal(t, "MEMBERSHIP_ROLE_MEMBER", it.Request.Body["role"])

	require.Equal(t, 200, it.Response.Status)
	membership, ok := it.Response.Body["membership"].(map[string]interface{})
	require.True(t, ok, "response must wrap the created row in a membership object")
	require.Equal(t, "00000000-0000-0000-0000-000000000d02", membership["id"])
	require.Equal(t, orgID, membership["tenant_id"])
	require.Equal(t, addUserID, membership["user_id"])
	require.Equal(t, "MEMBERSHIP_ROLE_MEMBER", membership["role"])
}

// TestPactOrgContract_RemoveMember pins the remove-member interaction: an org
// ADMIN removes a MEMBER; RemoveMemberResponse is empty, so orgclient.RemoveMember
// returns only an error (nil on success). The empty response body MUST be {}.
func TestPactOrgContract_RemoveMember(t *testing.T) {
	c := loadOrgContract(t)

	it, ok := findInteraction(c, removePath, removeUserID)
	require.True(t, ok, "contract must declare a RemoveMember interaction")

	require.Len(t, it.ProviderStates, 1)
	require.Equal(t,
		"caller "+callerID+" is an ADMIN of org "+orgID+" and user "+removeUserID+" is a MEMBER of workspace "+orgID,
		it.ProviderStates[0].Name,
		"provider state must seed the caller's ADMIN authz AND the target membership to remove")

	require.Equal(t, "POST", it.Request.Method)
	require.Equal(t, orgID, it.Request.Body["tenant_id"])
	require.Equal(t, removeUserID, it.Request.Body["user_id"])
	// RemoveMember carries no role — only tenant_id + user_id identify the row.
	_, hasRole := it.Request.Body["role"]
	require.False(t, hasRole, "RemoveMember request must not carry a role field")

	require.Equal(t, 200, it.Response.Status)
	require.Empty(t, it.Response.Body,
		"RemoveMemberResponse is empty — the response body must be {} (no fields on the wire)")
}

// TestPactOrgContract_CheckUserRemovable pins the platform-delete pre-flight
// interaction (admin-bff's Delete fan-out calls this once per org before
// mutating any of them — see platform_users.go): a plain MEMBER is reported
// as removable (is_sole_owner=false).
func TestPactOrgContract_CheckUserRemovable(t *testing.T) {
	c := loadOrgContract(t)

	it := findInteractionByPath(t, c, checkRemovablePath)

	require.Len(t, it.ProviderStates, 1)
	require.Equal(t,
		"a user with keycloak id "+checkRemovableUserID+" is a MEMBER of the org",
		it.ProviderStates[0].Name,
		"provider state must seed the target's plain MEMBER role")

	require.Equal(t, "POST", it.Request.Method)
	require.Equal(t, checkRemovableOrgID, it.Request.Body["org_id"])
	require.Equal(t, checkRemovableUserID, it.Request.Body["user_id"])

	require.Equal(t, 200, it.Response.Status)
	require.Equal(t, false, it.Response.Body["is_sole_owner"],
		"a plain MEMBER must not be reported as the sole owner")
}

// TestPactOrgContract_ListMembershipsByTenant_Workspace pins the roster read
// admin-mfe's AssignUserModal performs against a CHILD workspace. org-svc's
// authorizeRosterRead gates workspace targets (unlike the deliberately
// permissive org-root branch studio-bff depends on): an org OWNER/ADMIN, a
// workspace-ADMIN delegate, or any member of that workspace may read it.
// This interaction covers the org-ADMIN caller arm.
func TestPactOrgContract_ListMembershipsByTenant_Workspace(t *testing.T) {
	c := loadOrgContract(t)

	it := findInteractionByPath(t, c, rosterPath)
	require.Equal(t, "an org admin reads a workspace roster", it.Description)

	require.Len(t, it.ProviderStates, 1)
	require.Equal(t,
		"caller "+callerID+" is an ADMIN of org "+orgID+" and workspace "+workspaceID+" is a child of that org",
		it.ProviderStates[0].Name,
		"provider state must seed the caller's org-root ADMIN authz AND a CHILD workspace tenant")

	require.Equal(t, "POST", it.Request.Method)
	require.Equal(t, workspaceID, it.Request.Body["tenant_id"],
		"the request must target the child workspace — an org-root target would exercise the ungated branch")
	require.NotEqual(t, orgID, it.Request.Body["tenant_id"])
	// The roster read identifies no subject user: it returns the whole tenant.
	_, hasUser := it.Request.Body["user_id"]
	require.False(t, hasUser, "ListMembershipsByTenant request must not carry a user_id field")

	require.Equal(t, 200, it.Response.Status)
	memberships, ok := it.Response.Body["memberships"].([]interface{})
	require.True(t, ok, "response must carry a memberships array")
	require.Len(t, memberships, 1, "the contract declares exactly one roster row")

	row, ok := memberships[0].(map[string]interface{})
	require.True(t, ok, "each roster row must be an object")
	require.Equal(t, "00000000-0000-0000-0000-000000000d01", row["id"])
	require.Equal(t, workspaceID, row["tenant_id"],
		"the roster row belongs to the workspace the request targeted, not the org root")
	require.Equal(t, updateUserID, row["user_id"])
	require.Equal(t, "MEMBERSHIP_ROLE_MEMBER", row["role"])
}



